CREATE TABLE import_jobs (id VARCHAR(80) PRIMARY KEY, owner_id VARCHAR(80) NOT NULL REFERENCES users(id), identity_revision BIGINT NOT NULL, dataset VARCHAR(32) NOT NULL, state VARCHAR(20) NOT NULL, revision BIGINT NOT NULL, created_at VARCHAR(40) NOT NULL, expires_at VARCHAR(40) NOT NULL, baseline VARCHAR(64) NOT NULL, skipped_examples INT NOT NULL, repeated_rows INT NOT NULL, row_count INT NOT NULL, result_id VARCHAR(80), confirm_hash VARCHAR(64));
CREATE INDEX idx_import_jobs_owner ON import_jobs(owner_id,created_at);
CREATE TABLE import_job_rows (job_id VARCHAR(80) NOT NULL REFERENCES import_jobs(id), row_number INT NOT NULL, incoming CLOB NOT NULL, previous CLOB NOT NULL, source_sheet VARCHAR(200) NOT NULL, source_row INT NOT NULL, similar_count INT NOT NULL, pending_count INT NOT NULL, choice VARCHAR(20) NOT NULL, PRIMARY KEY(job_id,row_number));
